import { Component, Input, Output, EventEmitter, OnInit } from '@angular/core';
import { Product } from 'src/app/Modals/Product';
import { ProductService } from 'src/app/services/product.service';

@Component({
  selector: 'product-items',
  templateUrl: './product-items.component.html',
  styleUrls: ['./product-items.component.css']
})
export class ProductItemsComponent implements OnInit {
  @Input() searchText: string = '';
  @Output() productSelected = new EventEmitter<Product>();

  selectedFilterRadioButton: string = 'all';
  products: Product[] = [];
  loading: boolean = true;

  constructor(private productService: ProductService) {}

  ngOnInit(): void {
    this.productService.getProducts().subscribe({
      next: (data) => {
        this.products = data && data.length > 0 ? data : this.getDefaultProducts();
        this.loading = false;
      },
      error: () => {
        this.products = this.getDefaultProducts();
        this.loading = false;
      }
    });
  }

  get totalProductsCount(): number {
    return this.products.length;
  }

  get productInStock(): number {
    return this.products.filter(p => p.is_in_inventory || p.isInInventory).length;
  }

  get productOutOfStock(): number {
    return this.products.filter(p => !(p.is_in_inventory || p.isInInventory)).length;
  }

  onFilterChanged(value: string) {
    this.selectedFilterRadioButton = value;
  }

  viewProduct(product: Product) {
    this.productSelected.emit(product);
  }

  get filteredProducts(): Product[] {
    return this.products.filter(prod => {
      const matchSearch =
        this.searchText === '' || prod.name.toLowerCase().includes(this.searchText.toLowerCase());

      const inInventory = prod.is_in_inventory || prod.isInInventory;

      const matchFilter =
        this.selectedFilterRadioButton === 'all' ||
        (this.selectedFilterRadioButton === 'inStock' && inInventory) ||
        (this.selectedFilterRadioButton === 'outOfStock' && !inInventory);

      return matchSearch && matchFilter;
    });
  }

  private getDefaultProducts(): Product[] {
    return [
      {
        id: 1,
        name: "Nike React Infinity Run Flyknit",
        description: "Cushioned running shoe engineered for maximum comfort.",
        brand: "NIKE",
        gender: "MEN",
        category: "RUNNING", 
        size: [6, 7, 8, 9, 10],
        color: ["white", "Blue", "Black"],
        price: 1299,
        discountPrice : 899,
        is_in_inventory: true,
        items_left: 6,
        imageURL: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSL7v5qwkXDHAkzLm7cra136dR7EnADq1Nqdg&s", 
        slug: "nike-react-infinity-run-flyknit"
      },
      {
        id: 2,
        name: "Adidas Stylish Shoes",
        description: "Sleek casual shoes for street style.",
        brand: "ADIDAS",
        gender: "MEN",
        category: "CASUAL", 
        size: [7, 8, 9, 10],
        color: ["Pink", "White", "Black"],
        discountPrice : 1099,
        price: 1499,
        is_in_inventory: false,
        items_left: 0,
        imageURL: "https://img.tatacliq.com/images/i18//437Wx649H/MP000000022902708_437Wx649H_202407131602401.jpeg", 
        slug: "adidas-stylish-shoes"
      }
    ];
  }
}
<!-- Filter Component -->
<app-filter
  [all]="totalProductsCount"
  [inStock]="productInStock"
  [outOfstock]="productOutOfStock"
  (productSelectedButtonChanged)="onFilterChanged($event)">
</app-filter>

<!-- Product Grid -->
<div class="ekart--products--container">
  <ng-container *ngFor="let prod of filteredProducts">
    <app-product
      class="ekart--product--card"
      [product]="prod"
      (click)="viewProduct(prod)">
    </app-product>
  </ng-container>
</div>
